A minimal, standard-library-only client for OpenAI Responses API.

- No third-party dependencies
- Supports both non-streaming and streaming requests
- Reads API key from "'`OPENAI_API_KEY` by default
"""
from __future__ import annotations

import json
import os
import ssl
import sys
import urllib.error
import urllib.request
from typing import Dict, Iterable, Iterator, Optional

__all__ = [
    "OpenAIClient",
    "OpenAIAPIError",
]


DEFAULT_BASE_URL = "https://api.openai.com/v1"
RESPONSES_PATH = "/responses"


class OpenAIAPIError(RuntimeError):
    """Raised when the OpenAI API returns a non-2xx response.

    Attributes:
        status: HTTP status code
        body: Raw response body (str)
        headers: Mapping of response headers (dict)
    """

    def __init__(self, message: str, *, status: int, body: str, headers: Dict[str, str]):
        super().__init__(message)
        self.status = status
        self.body = body
        self.headers = headers

    def __str__(self) -> str:
        return f"OpenAIAPIError(status={self.status}, message={super().__str__()})'"\\n{self.body}\"


class OpenAIClient:
    \"\"\"Lightweight client for the OpenAI Responses API using only stdlib.

    Args:
        api_key: OpenAI API key. If None, reads from env var OPENAI_API_KEY.
        base_url: Override the API base URL (default: https://api.openai.com/v1).
        timeout: Socket timeout in seconds for request and response operations.
        organization: Optional organization ID. If None, reads OPENAI_ORG_ID or OPENAI_ORGANIZATION.
        user_agent: Optional User-Agent header value.
        verify_tls: When False, disables certificate verification (not recommended).

    Methods:
        create_response(...): Perform a single, non-streaming prompt request.
        stream_response(...): Stream Server-Sent Events (SSE) for incremental output.
        get_text(obj): Best-effort text extraction helper from the JSON structure.
    \"\"\"

    def __init__(
        self,
        api_key: [REDACTED_SECRET] = None,
        *,
        base_url: str = DEFAULT_BASE_URL,
        timeout: Optional[float] = 60.0,
        organization: Optional[str] = None,
        user_agent: Optional[str] = None,
        verify_tls: bool = True,
    ) -> None:
        self.api_key = api_key or os.getenv(\"OPENAI_API_KEY\")
        if not self.api_key:
            raise ValueError(
                \"Missing OpenAI API key. Set OPENAI_API_KEY or pass api_key=...\"
            )

        self.base_url = base_url.rstrip(\"/\")
        self.timeout = timeout
        self.organization = (
            organization
            or os.getenv(\"OPENAI_ORG_ID\")
            or os.getenv(\"OPENAI_ORGANIZATION\")
        )
        self.user_agent = user_agent or self._default_user_agent()
        self._ssl_context = self._make_ssl_context(verify_tls)

    def create_response(
        self,
        *,
        input: str,
        model: str = \"gpt-4.1-mini\",
        system: Optional[str] = None,
        temperature: Optional[float] = None,
        max_output_tokens: Optional[int] = None,
        extra_headers: Optional[Dict[str, str]] = None,
        extra_body: Optional[Dict] = None,
        metadata: Optional[Dict[str, str]] = None,
    ) -> Dict:
        \"\"\"Send a non-streaming prompt to the Responses API and return parsed JSON.
        \"\"\"
        body: Dict[str, object] = {\"model\": model, \"input\": input}
        if system is not None:
            body[\"system\"] = system
        if temperature is not None:
            body[\"temperature\"] = float(temperature)
        if max_output_tokens is not None:
            body[\"max_output_tokens\"] = int(max_output_tokens)
        if metadata is not None:
            body[\"metadata\"] = metadata
        if extra_body:
            body.update(extra_body)

        req = self._build_request(path=RESPONSES_PATH, json_body=body, headers=extra_headers)
        try:
            with urllib.request.urlopen(req, context=self._ssl_context, timeout=self.timeout) as resp:
                data = resp.read()
                return json.loads(data.decode(\"utf-8\"))
        except urllib.error.HTTPError as e:
            self._raise_api_error(e)
        except urllib.error.URLError as e:
            raise ConnectionError(f\"Failed to connect to OpenAI API: {e}\") from e

    def stream_response(
        self,
        *,
        input: str,
        model: str = \"gpt-4.1-mini\",
        system: Optional[str] = None,
        temperature: Optional[float] = None,
        max_output_tokens: Optional[int] = None,
        extra_headers: Optional[Dict[str, str]] = None,
        extra_body: Optional[Dict] = None,
        metadata: Optional[Dict[str, str]] = None,
    ) -> Iterator[Dict[str, object]]:
        \"\"\"Stream incremental output via SSE. Yields event dicts with keys event and data.
        \"\"\"
        body: Dict[str, object] = {\"model\": model, \"input\": input, \"stream\": True}
        if system is not None:
            body[\"system\"] = system
        if temperature is not None:
            body[\"temperature\"] = float(temperature)
        if max_output_tokens is not None:
            body[\"max_output_tokens\"] = int(max_output_tokens)
        if metadata is not None:
            body[\"metadata\"] = metadata
        if extra_body:
            body.update(extra_body)

        headers = {\"Accept\": \"text/event-stream\"}
        if extra_headers:
            headers.update(extra_headers)

        req = self._build_request(path=RESPONSES_PATH, json_body=body, headers=headers)
        try:
            with urllib.request.urlopen(req, context=self._ssl_context, timeout=self.timeout) as resp:
                for event in _iter_sse(resp):
                    yield event
        except urllib.error.HTTPError as e:
            self._raise_api_error(e)
        except urllib.error.URLError as e:
            raise ConnectionError(f\"Failed to connect to OpenAI API: {e}\") from e

    @staticmethod
    def get_text(obj: Dict) -> str:
        \"\"\"Best-effort extraction of assistant text from a Responses result.
        \"\"\"
        if not isinstance(obj, dict):
            return \"\"
        data = obj.get(\"response\") if isinstance(obj.get(\"response\"), dict) else obj
        for k in (\"output_text\", \"text\", \"content_text\"):
            v = data.get(k)
            if isinstance(v, str):
                return v
        out = []
        output = data.get(\"output\")
        if isinstance(output, list):
            for item in output:
                if not isinstance(item, dict):
                    continue
                parts = item.get(\"content\")
                if isinstance(parts, list):
                    for p in parts:
                        if not isinstance(p, dict):
                            continue
                        txt = p.get(\"text\") or p.get(\"content\") or p.get(\"value\")
                        if isinstance(txt, str):
                            out.append(txt)
        return \"\".join(out)

    def _default_user_agent(self) -> str:
        py = f\"Python/{sys.version_info.major}.{sys.version_info.minor}.{sys.version_info.micro}\"
        return f\"openai-client-stdlib/1.0 ({py}; urllib)\"

    def _make_ssl_context(self, verify_tls: bool) -> ssl.SSLContext:
        ctx = ssl.create_default_context()
        if not verify_tls:
            ctx.check_hostname = False
            ctx.verify_mode = ssl.CERT_NONE
        return ctx

    def _build_request(
        self,
        *,
        path: str,
        json_body: Dict[str, object],
        headers: Optional[Dict[str, str]] = None,
    ) -> urllib.request.Request:
        url = f\"{self.base_url}{path}\"
        data = json.dumps(json_body, separators=(\",\", \":\")).encode(\"utf-8\")

        req_headers = {
            \"Authorization\": f\"Bearer {self.api_key}\",
            \"Content-Type\": \"application/json\",
            \"User-Agent\": self.user_agent,
        }
        if self.organization:
            req_headers[\"OpenAI-Organization\"] = self.organization
        if headers:
            req_headers.update(headers)

        return urllib.request.Request(url=url, data=data, headers=req_headers, method=\"POST\")

    def _raise_api_error(self, e: urllib.error.HTTPError) -> None:
        try:
            body = e.read().decode(\"utf-8\")
        except Exception:
            body = \"\"
        headers = {k: v for k, v in getattr(e, \"headers\", {}).items()} if hasattr(e, \"headers\") else {}
        reason = getattr(e, \"reason\", None) or \"\"
        msg = f\"OpenAI API error {e.code} {reason}\".strip()
        raise OpenAIAPIError(msg, status=e.code, body=body, headers=headers) from e


def _iter_sse(resp: Iterable[bytes]) -> Iterator[Dict[str, object]]:
    \"\"\"Iterate Server-Sent Events from a file-like HTTP response.

    Parses events with fields like lines starting with event: and data:.
    Data lines are joined with newlines. Tries to parse JSON, falls back to text.
    \"\"\"
    event_name: Optional[str] = None
    data_lines: list[str] = []

    def flush() -> Iterator[Dict[str, object]]:
        nonlocal event_name, data_lines
        if not data_lines and event_name is None:
            return iter(())
        raw_data = \"\\n\".join(data_lines)
        try:
            payload: object = json.loads(raw_data)
        except Exception:
            payload = raw_data
        evt = {\"event\": event_name or \"message\", \"data\": payload}
        event_name = None
        data_lines = []
        return iter((evt,))

    while True:
        line = resp.readline()
        if not line:
            yield from flush()
            break
        try:
            s = line.decode(\"utf-8\")
        except Exception:
            s = line.decode(\"utf-8\", errors=\"replace\")
        s = s.rstrip(\"\\r\\n\")
        if not s:
            yield from flush()
            continue
        if s.startswith(\":\"):
            continue
        if s.startswith(\"event:\"):
            event_name = s[len(\"event:\") :].strip() or None
            continue
        if s.startswith(\"data:\"):
            data_lines.append(s[len(\"data:\") :].lstrip())
            continue


